//! Differential test: the Responses stream translator must emit exactly the
//! same Anthropic event sequence as the Python implementation.
//!
//! Expectations were generated by running
//! `main/proxy/services/copilot/responses_stream_translation.py` over the same
//! event sequences. The subtle parts worth pinning are the sequential-block
//! closing (Anthropic allows only one open content block, so opening a new one
//! closes the previous), the `output_index`-keyed function-call identity, and
//! the `encrypted_content@id` reasoning signature.

use imc_proxy_copilot::responses_stream_translation::{
    translate_responses_stream_event, ResponsesStreamState,
};
use serde_json::{json, Value};

fn run(events: &[Value]) -> Vec<Value> {
    let mut state = ResponsesStreamState::default();
    let mut out: Vec<Value> = Vec::new();
    for e in events {
        out.extend(translate_responses_stream_event(e, &mut state));
    }
    out
}

fn assert_events(events: &[Value], expected: Value, case: &str) {
    assert_eq!(json!(run(events)), expected, "event mismatch in case {case}");
}

fn message_start(id: &str) -> Value {
    json!({"type": "message_start", "message": {
        "id": id, "type": "message", "role": "assistant", "content": [],
        "model": "gpt-5.3-codex", "stop_reason": null, "stop_sequence": null,
        "usage": {"input_tokens": 0, "output_tokens": 0}}})
}

fn usage(input: i64, output: i64, cached: i64, write: i64) -> Value {
    json!({"cache_creation_input_tokens": write, "cache_read_input_tokens": cached,
           "input_tokens": input, "output_tokens": output})
}

#[test]
fn reasoning_then_text_matches_python() {
    let events = vec![
        json!({"type": "response.created", "response": {"id": "resp_1", "model": "gpt-5.3-codex"}}),
        json!({"type": "response.reasoning_summary_text.delta", "output_index": 0, "delta": "thinking"}),
        json!({"type": "response.output_item.done", "output_index": 0,
               "item": {"type": "reasoning", "id": "rs_1", "encrypted_content": "ENCRYPTED"}}),
        json!({"type": "response.output_text.delta", "output_index": 1, "content_index": 0, "delta": "Hello"}),
        json!({"type": "response.output_text.delta", "output_index": 1, "content_index": 0, "delta": " world"}),
        json!({"type": "response.output_text.done", "output_index": 1, "content_index": 0, "text": "Hello world"}),
        json!({"type": "response.completed", "response": {"id": "resp_1", "usage": {
            "input_tokens": 100, "output_tokens": 20,
            "input_tokens_details": {"cached_tokens": 30, "cache_write_tokens": 7}}}}),
    ];

    assert_events(
        &events,
        json!([
            message_start("resp_1"),
            {"type": "content_block_start", "index": 0,
             "content_block": {"type": "thinking", "thinking": ""}},
            {"type": "content_block_delta", "index": 0,
             "delta": {"type": "thinking_delta", "thinking": "thinking"}},
            {"type": "content_block_delta", "index": 0,
             "delta": {"type": "signature_delta", "signature": "ENCRYPTED@rs_1"}},
            {"type": "content_block_stop", "index": 0},
            {"type": "content_block_start", "index": 1,
             "content_block": {"type": "text", "text": ""}},
            {"type": "content_block_delta", "index": 1,
             "delta": {"type": "text_delta", "text": "Hello"}},
            {"type": "content_block_delta", "index": 1,
             "delta": {"type": "text_delta", "text": " world"}},
            // output_text.done must not repeat the text already streamed.
            {"type": "content_block_stop", "index": 1},
            {"type": "message_delta", "delta": {"stop_reason": "end_turn", "stop_sequence": null},
             "usage": usage(100, 20, 30, 7)},
            {"type": "message_stop"}
        ]),
        "text_with_reasoning",
    );
}

#[test]
fn function_call_arguments_stream_into_one_block() {
    let events = vec![
        json!({"type": "response.created", "response": {"id": "resp_2", "model": "gpt-5.3-codex"}}),
        json!({"type": "response.output_item.added", "output_index": 0,
               "item": {"type": "function_call", "call_id": "call_1", "name": "Bash", "arguments": ""}}),
        json!({"type": "response.function_call_arguments.delta", "output_index": 0, "delta": "{\"command\":"}),
        json!({"type": "response.function_call_arguments.delta", "output_index": 0, "delta": "\"ls\"}"}),
        json!({"type": "response.function_call_arguments.done", "output_index": 0,
               "arguments": "{\"command\":\"ls\"}"}),
        json!({"type": "response.completed", "response": {"id": "resp_2", "usage": {
            "input_tokens": 10, "output_tokens": 5}}}),
    ];

    assert_events(
        &events,
        json!([
            message_start("resp_2"),
            {"type": "content_block_start", "index": 0,
             "content_block": {"type": "tool_use", "id": "call_1", "name": "Bash", "input": {}}},
            {"type": "content_block_delta", "index": 0,
             "delta": {"type": "input_json_delta", "partial_json": "{\"command\":"}},
            {"type": "content_block_delta", "index": 0,
             "delta": {"type": "input_json_delta", "partial_json": "\"ls\"}"}},
            // .done must not re-emit arguments already streamed as deltas.
            {"type": "content_block_stop", "index": 0},
            {"type": "message_delta", "delta": {"stop_reason": "end_turn", "stop_sequence": null},
             "usage": usage(10, 5, 0, 0)},
            {"type": "message_stop"}
        ]),
        "function_call",
    );
}

#[test]
fn prefilled_function_call_emits_arguments_once() {
    let events = vec![
        json!({"type": "response.output_item.added", "output_index": 0,
               "item": {"type": "function_call", "call_id": "c9", "name": "Read",
                        "arguments": "{\"path\":\"/tmp\"}"}}),
        json!({"type": "response.completed", "response": {"usage": {"input_tokens": 1, "output_tokens": 1}}}),
    ];

    // No response.created -> no message_start, matching Python.
    assert_events(
        &events,
        json!([
            {"type": "content_block_start", "index": 0,
             "content_block": {"type": "tool_use", "id": "c9", "name": "Read", "input": {}}},
            {"type": "content_block_delta", "index": 0,
             "delta": {"type": "input_json_delta", "partial_json": "{\"path\":\"/tmp\"}"}},
            {"type": "content_block_stop", "index": 0},
            {"type": "message_delta", "delta": {"stop_reason": "end_turn", "stop_sequence": null},
             "usage": usage(1, 1, 0, 0)},
            {"type": "message_stop"}
        ]),
        "function_call_prefilled",
    );
}

#[test]
fn incomplete_maps_to_max_tokens() {
    let events = vec![
        json!({"type": "response.created", "response": {"id": "resp_3", "model": "gpt-5.3-codex"}}),
        json!({"type": "response.output_text.delta", "output_index": 0, "content_index": 0, "delta": "part"}),
        json!({"type": "response.incomplete", "response": {"usage": {"input_tokens": 2, "output_tokens": 9}}}),
    ];

    assert_events(
        &events,
        json!([
            message_start("resp_3"),
            {"type": "content_block_start", "index": 0,
             "content_block": {"type": "text", "text": ""}},
            {"type": "content_block_delta", "index": 0,
             "delta": {"type": "text_delta", "text": "part"}},
            {"type": "content_block_stop", "index": 0},
            {"type": "message_delta", "delta": {"stop_reason": "max_tokens", "stop_sequence": null},
             "usage": usage(2, 9, 0, 0)},
            {"type": "message_stop"}
        ]),
        "incomplete",
    );
}

#[test]
fn failure_paths_close_blocks_and_emit_errors() {
    let failed = vec![
        json!({"type": "response.created", "response": {"id": "resp_4", "model": "gpt-5.3-codex"}}),
        json!({"type": "response.output_text.delta", "output_index": 0, "content_index": 0, "delta": "oops"}),
        json!({"type": "response.failed", "response": {}}),
    ];
    assert_events(
        &failed,
        json!([
            message_start("resp_4"),
            {"type": "content_block_start", "index": 0,
             "content_block": {"type": "text", "text": ""}},
            {"type": "content_block_delta", "index": 0,
             "delta": {"type": "text_delta", "text": "oops"}},
            {"type": "content_block_stop", "index": 0},
            // No message_delta/message_stop: the stream failed.
            {"type": "error", "error": {"type": "api_error", "message": "Response failed"}}
        ]),
        "failed",
    );

    let error_event = vec![
        json!({"type": "response.created", "response": {"id": "resp_5", "model": "gpt-5.3-codex"}}),
        json!({"type": "error", "message": "upstream exploded"}),
    ];
    assert_events(
        &error_event,
        json!([
            message_start("resp_5"),
            {"type": "error", "error": {"type": "api_error", "message": "upstream exploded"}}
        ]),
        "error_event",
    );
}

#[test]
fn ping_passes_through() {
    let events = vec![
        json!({"type": "response.created", "response": {"id": "resp_6", "model": "gpt-5.3-codex"}}),
        json!({"type": "ping"}),
        json!({"type": "ping"}),
    ];
    assert_events(
        &events,
        json!([message_start("resp_6"), {"type": "ping"}, {"type": "ping"}]),
        "ping",
    );
}

#[test]
fn interleaved_output_items_close_previous_block() {
    let events = vec![
        json!({"type": "response.output_text.delta", "output_index": 0, "content_index": 0, "delta": "before"}),
        json!({"type": "response.output_item.added", "output_index": 1,
               "item": {"type": "function_call", "call_id": "call_x", "name": "Bash", "arguments": "{}"}}),
        json!({"type": "response.output_text.delta", "output_index": 2, "content_index": 0, "delta": "after"}),
        json!({"type": "response.completed", "response": {"usage": {"input_tokens": 3, "output_tokens": 4}}}),
    ];

    // Opening the tool block closes the text block; opening the second text
    // block closes the tool block — the Anthropic one-open-block invariant.
    assert_events(
        &events,
        json!([
            {"type": "content_block_start", "index": 0,
             "content_block": {"type": "text", "text": ""}},
            {"type": "content_block_delta", "index": 0,
             "delta": {"type": "text_delta", "text": "before"}},
            {"type": "content_block_stop", "index": 0},
            {"type": "content_block_start", "index": 1,
             "content_block": {"type": "tool_use", "id": "call_x", "name": "Bash", "input": {}}},
            {"type": "content_block_delta", "index": 1,
             "delta": {"type": "input_json_delta", "partial_json": "{}"}},
            {"type": "content_block_stop", "index": 1},
            {"type": "content_block_start", "index": 2,
             "content_block": {"type": "text", "text": ""}},
            {"type": "content_block_delta", "index": 2,
             "delta": {"type": "text_delta", "text": "after"}},
            {"type": "content_block_stop", "index": 2},
            {"type": "message_delta", "delta": {"stop_reason": "end_turn", "stop_sequence": null},
             "usage": usage(3, 4, 0, 0)},
            {"type": "message_stop"}
        ]),
        "text_then_tool",
    );
}

#[test]
fn reasoning_without_encrypted_content_emits_no_signature() {
    let events = vec![
        json!({"type": "response.reasoning_summary_text.delta", "output_index": 0, "delta": "quiet"}),
        // Neither encrypted_content nor id: the signature reduces to a bare
        // "@", which Python treats as "nothing to send".
        json!({"type": "response.output_item.done", "output_index": 0, "item": {"type": "reasoning"}}),
        json!({"type": "response.completed", "response": {"usage": {"input_tokens": 1, "output_tokens": 1}}}),
    ];

    assert_events(
        &events,
        json!([
            {"type": "content_block_start", "index": 0,
             "content_block": {"type": "thinking", "thinking": ""}},
            {"type": "content_block_delta", "index": 0,
             "delta": {"type": "thinking_delta", "thinking": "quiet"}},
            {"type": "content_block_stop", "index": 0},
            {"type": "message_delta", "delta": {"stop_reason": "end_turn", "stop_sequence": null},
             "usage": usage(1, 1, 0, 0)},
            {"type": "message_stop"}
        ]),
        "reasoning_without_signature",
    );
}